    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint value, bytes memory data) public {
        require(value > address(c).balance, "value must exceed c balance");
        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && address(c).balance == balBefore && c.depositsCount() == countBefore);
    }

    receive() external payable {}
}

